require "rails_helper"

RSpec.describe Timekeeping::LocalOutboxSource do
  # "`unsent_after` returns that company's rows with `sent_at` nil and `outbox_position > position`, ascending,
  # at most `limit` rows. Each row is a Hash with the string keys `generation`, `outbox_position` and `entry`,
  # and `entry` holds exactly the contract fields."
  # "Read the jsonb payload from its raw text, so `duration` keeps its exact float bits and timestamps keep microseconds."
  it "returns only its company's unsent rows above the position, ascending and limited, with contract entries, microseconds and exact duration bits" do
    company_a = create(:company)
    company_b = create(:company)
    write = lambda do |company, duration, sent_at: nil, extra: {}|
      payload = TimekeepingSnapshots.entry(id: 900 + Timekeeping::LocalOutboxEntry.count, company_id: company.id,
                                           version: 1, project_id: nil, user_id: nil, duration:,
                                           created_at: "2026-03-02T09:00:00.123456Z")
      Timekeeping::LocalOutboxEntry.create!(company_id: company.id, entry_id: payload.fetch("id"), generation: 1,
                                            payload: payload.merge(extra), created_at: Time.current, sent_at:)
    end
    b_low = write.call(company_b, 1.0)
    a_sent = write.call(company_a, 2.0, sent_at: 1.hour.ago)
    a_first = write.call(company_a, 5e-324)
    b_mid = write.call(company_b, 3.0)
    a_second = write.call(company_a, 0.1 + 0.2, extra: { "sent_at" => "x" })
    a_third = write.call(company_a, 7.25)
    b_high = write.call(company_b, 4.0)
    source = described_class.new(company_id: company_a.id)

    rows = source.unsent_after(0, 100)

    expect(rows.map { |row| row["outbox_position"] })
      .to eq([a_first, a_second, a_third].map(&:outbox_position))
    expect(rows.map { |row| row["outbox_position"] })
      .not_to include(*[b_low, b_mid, b_high, a_sent].map(&:outbox_position))
    rows.each do |row|
      expect(row.keys).to contain_exactly("generation", "outbox_position", "entry")
      expect(row["entry"].keys).to match_array(Timekeeping::SnapshotBatch::ENTRY_FIELDS)
      expect(row["entry"]["created_at"]).to eq("2026-03-02T09:00:00.123456Z")
    end
    expect(rows.map { |row| [row["entry"]["duration"]].pack("G") })
      .to eq([5e-324, 0.1 + 0.2, 7.25].map { |value| [value].pack("G") })

    # The position bound is exclusive, and the limit keeps the first rows.
    expect(source.unsent_after(a_first.outbox_position, 100).map { |row| row["outbox_position"] })
      .to eq([a_second, a_third].map(&:outbox_position))
    expect(source.unsent_after(0, 2).map { |row| row["outbox_position"] })
      .to eq([a_first, a_second].map(&:outbox_position))
  end
end

