# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::LocalOutboxSource do
  def outbox_spec_payload(entry_id, company_id)
    Timekeeping::SnapshotBatch::ENTRY_FIELDS.index_with { nil }.merge(
      "id" => entry_id, "company_id" => company_id, "duration" => 30.0, "version" => 1,
      "created_at" => "2026-03-02T09:00:00.123456Z", "updated_at" => "2026-03-02T09:00:00.123456Z"
    )
  end

  def outbox_spec_row(company_id, entry_id)
    Timekeeping::LocalOutboxEntry.create!(
      company_id:, entry_id:, generation: 1, payload: outbox_spec_payload(entry_id, company_id), created_at: Time.current
    )
  end

  # "Every outbox read and mark filters by company_id; company A's source never returns or marks company B's rows"
  # Positions are one global sequence, so B's rows sit below, between and above A's rows: a source that
  # filtered only by position would return or mark them.
  it "company A's source given company B's interleaved positions neither returns nor marks them" do
    company_a = create(:company)
    company_b = create(:company)
    rows = [
      outbox_spec_row(company_b.id, 900), outbox_spec_row(company_a.id, 100), outbox_spec_row(company_b.id, 901),
      outbox_spec_row(company_a.id, 101), outbox_spec_row(company_b.id, 902)
    ]
    a_positions = rows.select { |row| row.company_id == company_a.id }.map(&:outbox_position)
    b_positions = rows.select { |row| row.company_id == company_b.id }.map(&:outbox_position)
    source_a = described_class.new(company_id: company_a.id)

    returned = source_a.unsent_after(0, 100)
    source_a.mark_sent(b_positions)

    expect(returned.map { |row| row.fetch("outbox_position") }).to eq(a_positions)
    expect(Timekeeping::LocalOutboxEntry.where(outbox_position: b_positions).pluck(:sent_at)).to all(be_nil)
    expect(described_class.new(company_id: company_b.id).unsent_after(0, 100).map { |row| row.fetch("outbox_position") })
      .to eq(b_positions)
  end
end

